package com.electionsignal.polling;

import java.sql.*;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.context.annotation.Profile;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;

/** Public reads are limited to explicitly reviewed, redistributable individual sources. */
@Service
@Profile("local")
public class PollingReadService {
    private final DataSource database;
    public PollingReadService(DataSource database){this.database=database;}
    private int number(Map<String,String> p,String name,int fallback,int min,int max){try{int n=Integer.parseInt(p.getOrDefault(name,Integer.toString(fallback)));if(n<min||n>max)throw new NumberFormatException();return n;}catch(NumberFormatException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid "+name);}}
    private static void identity(String value,String field){if(value!=null&&!value.matches("[A-Za-z0-9_.:-]{1,100}"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid "+field);}
    private static Timestamp date(String value,boolean nextDay){try{var d=LocalDate.parse(value);return Timestamp.from((nextDay?d.plusDays(1):d).atStartOfDay().toInstant(ZoneOffset.UTC));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid publication date");}}
    private static Timestamp asOf(String value){try{return Timestamp.from(java.time.Instant.parse(value));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid asOf timestamp");}}
    private static void filter(StringBuilder sql,List<Object> args,String clause,Object value){if(value!=null){sql.append(clause);args.add(value);}}
    private static void bind(PreparedStatement q,List<Object> args)throws SQLException{for(int i=0;i<args.size();i++)q.setObject(i+1,args.get(i));}
    private static String instant(Timestamp t){return t==null?null:t.toInstant().toString();}
    private static Map<String,Object> envelope(String mode,String status,Object data){var source=new LinkedHashMap<String,Object>();source.put("provider",null);source.put("sourceAsOf",null);source.put("attribution","Per-record source and usage rights");var body=new LinkedHashMap<String,Object>();body.put("schemaVersion","1.0");body.put("dataMode",mode);body.put("isTestData",false);body.put("status",status);body.put("source",source);body.put("data",data);return body;}
    private static final Set<String> COMMON=Set.of("mode","year","office","state","district","provider","pollView","view","race","candidate","pollId","forecastId","dateFrom","dateTo","asOf","page","pageSize","pollster","population");
    private void validate(Map<String,String> p){for(String key:p.keySet())if(!COMMON.contains(key))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported filter: "+key);for(String key:List.of("race","candidate","pollId","forecastId","pollster","population"))identity(p.get(key),key);}
    public Object polls(Map<String,String> p)throws SQLException {
        validate(p);if(p.containsKey("forecastId"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Forecast filter does not apply to polls");int year=number(p,"year",2026,2000,2100),page=number(p,"page",0,0,100000),size=number(p,"pageSize",50,1,100);String office=p.getOrDefault("office","all").toUpperCase(Locale.ROOT),state=p.get("state"),district=p.get("district"),provider=p.get("provider");
        var args=new ArrayList<Object>();args.add(year);
        var sql=new StringBuilder("SELECT s.survey_id,s.office,s.state_code,s.district_code,s.race_id,s.field_start,s.field_end,s.sample_size,s.population,s.survey_mode,s.margin_of_error,s.sponsor,s.question_identity,s.matchup_identity,ps.display_name,p.publication_id,p.published_at,p.fetched_at,src.provider_id,src.publication_url,src.methodology_url,src.license_id,src.attribution FROM poll_surveys s JOIN pollsters ps ON ps.pollster_id=s.pollster_id JOIN LATERAL (SELECT pp.* FROM poll_publications pp JOIN polling_sources x ON x.source_id=pp.source_id WHERE pp.survey_id=s.survey_id AND x.review_status='APPROVED' AND x.redistribution_allowed=true ");
        filter(sql,args," AND x.provider_id=?",provider==null||provider.equals("all")?null:provider);filter(sql,args," AND pp.published_at>=?",p.get("dateFrom")==null?null:date(p.get("dateFrom"),false));filter(sql,args," AND pp.published_at<?",p.get("dateTo")==null?null:date(p.get("dateTo"),true));filter(sql,args," AND pp.published_at<=?",p.get("asOf")==null?null:asOf(p.get("asOf")));
        sql.append(" ORDER BY pp.published_at DESC NULLS LAST,pp.fetched_at DESC,pp.publication_id DESC LIMIT 1) p ON true JOIN polling_sources src ON src.source_id=p.source_id WHERE s.election_year=?");
        // The lateral query appears before the outer year predicate, so bind its arguments first.
        Object y=args.remove(0);args.add(y);
        filter(sql,args," AND s.office=?",office.equals("ALL")?null:office);filter(sql,args," AND s.state_code=?",state==null?null:state.toUpperCase(Locale.ROOT));filter(sql,args," AND s.district_code=?",district);filter(sql,args," AND s.race_id=?",p.get("race"));filter(sql,args," AND s.survey_id=?",p.get("pollId"));filter(sql,args," AND s.pollster_id=?",p.get("pollster"));filter(sql,args," AND s.population=?",p.get("population"));filter(sql,args," AND EXISTS (SELECT 1 FROM poll_answers a WHERE a.publication_id=p.publication_id AND a.candidate_id=?)",p.get("candidate"));sql.append(" ORDER BY p.published_at DESC NULLS LAST,s.survey_id LIMIT ? OFFSET ?");args.add(size);args.add(page*size);
        var data=new ArrayList<Map<String,Object>>();try(var c=database.getConnection();var q=c.prepareStatement(sql.toString())){bind(q,args);try(var r=q.executeQuery()){while(r.next()){var item=new LinkedHashMap<String,Object>();item.put("pollId",r.getString(1));item.put("office",r.getString(2));item.put("state",r.getString(3)==null?null:r.getString(3).trim());item.put("district",r.getString(4));item.put("raceId",r.getString(5));item.put("fieldStart",r.getObject(6));item.put("fieldEnd",r.getObject(7));item.put("sampleSize",r.getObject(8));item.put("population",r.getString(9));item.put("surveyMode",r.getString(10));item.put("marginOfError",r.getBigDecimal(11));item.put("sponsor",r.getString(12));item.put("questionIdentity",r.getString(13));item.put("matchupIdentity",r.getString(14));item.put("pollster",r.getString(15));long publication=r.getLong(16);item.put("publishedAt",instant(r.getTimestamp(17)));item.put("fetchedAt",instant(r.getTimestamp(18)));item.put("provider",r.getString(19));item.put("publicationUrl",r.getString(20));item.put("methodologyUrl",r.getString(21));item.put("license",r.getString(22));item.put("attribution",r.getString(23));var answers=new ArrayList<Map<String,Object>>();try(var aq=c.prepareStatement("SELECT choice_id,choice_label,candidate_id,response_percent FROM poll_answers WHERE publication_id=? ORDER BY choice_id")){aq.setLong(1,publication);try(var ar=aq.executeQuery()){while(ar.next()){var a=new LinkedHashMap<String,Object>();a.put("choiceId",ar.getString(1));a.put("label",ar.getString(2));a.put("candidateId",ar.getString(3));a.put("percent",ar.getBigDecimal(4));answers.add(a);}}}item.put("answers",answers);data.add(item);}}}
        var result=envelope("POLL",data.isEmpty()?"NOT_CONNECTED":"AVAILABLE",data);result.put("page",page);result.put("pageSize",size);return result;
    }
    public Object forecasts(Map<String,String> p)throws SQLException {
        validate(p);if(p.containsKey("pollster")||p.containsKey("population")||p.containsKey("pollId"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Poll-specific filters do not apply to forecasts");int year=number(p,"year",2026,2000,2100),page=number(p,"page",0,0,100000),size=number(p,"pageSize",50,1,100);
        String office=p.getOrDefault("office","all").toUpperCase(Locale.ROOT),provider=p.get("provider");
        var sql=new StringBuilder("SELECT f.forecast_id,f.election_year,f.office,f.state_code,f.district_code,f.race_id,f.candidate_id,f.published_at,f.fetched_at,f.expected_share,f.win_probability,f.interval_low,f.interval_high,f.rating,m.model_name,m.model_version,s.provider_id,s.publication_url,s.methodology_url,s.license_id,s.attribution FROM published_forecast_snapshots f JOIN published_forecast_models m ON m.model_id=f.model_id JOIN polling_sources s ON s.source_id=m.source_id WHERE f.election_year=? AND s.review_status='APPROVED' AND s.redistribution_allowed=true");
        var args=new ArrayList<Object>();args.add(year);filter(sql,args," AND f.office=?",office.equals("ALL")?null:office);filter(sql,args," AND f.state_code=?",p.get("state")==null?null:p.get("state").toUpperCase(Locale.ROOT));filter(sql,args," AND f.district_code=?",p.get("district"));filter(sql,args," AND f.race_id=?",p.get("race"));filter(sql,args," AND f.forecast_id=?",p.get("forecastId"));filter(sql,args," AND f.candidate_id=?",p.get("candidate"));filter(sql,args," AND s.provider_id=?",provider==null||provider.equals("all")?null:provider);filter(sql,args," AND f.published_at>=?",p.get("dateFrom")==null?null:date(p.get("dateFrom"),false));filter(sql,args," AND f.published_at<?",p.get("dateTo")==null?null:date(p.get("dateTo"),true));filter(sql,args," AND f.published_at<=?",p.get("asOf")==null?null:asOf(p.get("asOf")));sql.append(" ORDER BY f.published_at DESC,f.forecast_id LIMIT ? OFFSET ?");args.add(size);args.add(page*size);
        var data=new ArrayList<Map<String,Object>>();try(var c=database.getConnection();var q=c.prepareStatement(sql.toString())){bind(q,args);try(var r=q.executeQuery()){while(r.next()){var item=new LinkedHashMap<String,Object>();item.put("forecastId",r.getString(1));item.put("year",r.getInt(2));item.put("office",r.getString(3));item.put("state",r.getString(4)==null?null:r.getString(4).trim());item.put("district",r.getString(5));item.put("raceId",r.getString(6));item.put("candidateId",r.getString(7));item.put("publishedAt",instant(r.getTimestamp(8)));item.put("fetchedAt",instant(r.getTimestamp(9)));item.put("expectedShare",r.getBigDecimal(10));item.put("winProbability",r.getBigDecimal(11));item.put("intervalLow",r.getBigDecimal(12));item.put("intervalHigh",r.getBigDecimal(13));item.put("rating",r.getString(14));item.put("modelName",r.getString(15));item.put("modelVersion",r.getString(16));item.put("provider",r.getString(17));item.put("publicationUrl",r.getString(18));item.put("methodologyUrl",r.getString(19));item.put("license",r.getString(20));item.put("attribution",r.getString(21));data.add(item);}}}
        var result=envelope("PUBLISHED_FORECAST",data.isEmpty()?"NOT_CONNECTED":"AVAILABLE",data);result.put("page",page);result.put("pageSize",size);return result;
    }

    public Object averages(Map<String,String> p)throws SQLException {
        validate(p);if(p.containsKey("pollster")||p.containsKey("population")||p.containsKey("pollId")||p.containsKey("forecastId"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Record-specific filters do not apply to averages");int year=number(p,"year",2026,2000,2100),page=number(p,"page",0,0,100000),size=number(p,"pageSize",50,1,100);
        String office=p.getOrDefault("office","all").toUpperCase(Locale.ROOT),provider=p.get("provider");
        var sql=new StringBuilder("SELECT a.series_id,a.office,a.state_code,a.district_code,a.race_id,p.candidate_id,p.published_at,p.fetched_at,p.share,p.included_poll_count,s.provider_id,s.publication_url,a.methodology_url,s.license_id,s.attribution FROM poll_average_series a JOIN poll_average_points p ON p.series_id=a.series_id JOIN polling_sources s ON s.source_id=a.source_id WHERE a.election_year=? AND s.review_status='APPROVED' AND s.redistribution_allowed=true");
        var args=new ArrayList<Object>();args.add(year);filter(sql,args," AND a.office=?",office.equals("ALL")?null:office);filter(sql,args," AND a.state_code=?",p.get("state")==null?null:p.get("state").toUpperCase(Locale.ROOT));filter(sql,args," AND a.district_code=?",p.get("district"));filter(sql,args," AND a.race_id=?",p.get("race"));filter(sql,args," AND p.candidate_id=?",p.get("candidate"));filter(sql,args," AND s.provider_id=?",provider==null||provider.equals("all")?null:provider);filter(sql,args," AND p.published_at>=?",p.get("dateFrom")==null?null:date(p.get("dateFrom"),false));filter(sql,args," AND p.published_at<?",p.get("dateTo")==null?null:date(p.get("dateTo"),true));filter(sql,args," AND p.published_at<=?",p.get("asOf")==null?null:asOf(p.get("asOf")));sql.append(" ORDER BY p.published_at DESC,a.series_id,p.candidate_id LIMIT ? OFFSET ?");args.add(size);args.add(page*size);
        var data=new ArrayList<Map<String,Object>>();try(var c=database.getConnection();var q=c.prepareStatement(sql.toString())){bind(q,args);try(var r=q.executeQuery()){while(r.next()){var item=new LinkedHashMap<String,Object>();item.put("seriesId",r.getString(1));item.put("office",r.getString(2));item.put("state",r.getString(3)==null?null:r.getString(3).trim());item.put("district",r.getString(4));item.put("raceId",r.getString(5));item.put("candidateId",r.getString(6));item.put("publishedAt",instant(r.getTimestamp(7)));item.put("fetchedAt",instant(r.getTimestamp(8)));item.put("averageShare",r.getBigDecimal(9));item.put("includedPollCount",r.getObject(10));item.put("provider",r.getString(11));item.put("publicationUrl",r.getString(12));item.put("methodologyUrl",r.getString(13));item.put("license",r.getString(14));item.put("attribution",r.getString(15));data.add(item);}}}
        var result=envelope("POLL",data.isEmpty()?"NOT_CONNECTED":"AVAILABLE",data);result.put("page",page);result.put("pageSize",size);return result;
    }

}
